import { rolldown } from 'rolldown';
import { readFile, writeFile, mkdir } from 'node:fs/promises';
const bundle = await rolldown({ input: 'src/review/server-contract.ts', platform: 'neutral' });
try {
  const { output } = await bundle.generate({ format: 'esm' });
  const content =
    '// @ts-nocheck\n// Generated by node scripts/build-review.mjs. No private data.\n' +
    output[0].code;
  const directory = 'supabase/functions/revisao-ficha';
  const path = directory + '/contract.generated.ts';
  if (process.argv.includes('--check')) {
    if ((await readFile(path, 'utf8')) !== content) throw new Error('Regenerate review contract');
  } else {
    await mkdir(directory, { recursive: true });
    await writeFile(path, content);
  }
} finally {
  await bundle.close();
}
